const { TFGpt2LMHeadModel } = require('@tensorflow/tfjs');

async function generateCode(prompt, maxLength = 100, numReturnSequences = 1) {
  const tokenizer = await new TFGpt2Tokenizer();
  const model = await new TFGpt2LMHeadModel();
  const inputIds = tokenizer.encode(prompt);
  const output = model.generate(inputIds, {
    maxLength,
    numReturnSequences,
    noRepeatNgramSize: 2,
    temperature: 0.7,
    topK: 50,
    topP: 0.95,
    padTokenId: tokenizer.eosTokenId,
  });
  return output.map((seq) => tokenizer.decode(seq, { skipSpecialTokens: true }));
}

// Load the fine-tuned model
async function main() {
  const modelPromise = new Promise((resolve) => {
    resolve({
      model: await new TFGpt2LMHeadModel(),
      tokenizer: await new TFGpt2Tokenizer(),
    });
  });
  const { model, tokenizer } = await modelPromise;
  process.stdin.setEncoding('utf8');
  process.stdin.on('data', async (data) => {
    prompt = data.toString().trim();
    const generatedCode = await generateCode(prompt);
    console.log('Generated code:');
    console.log(generatedCode[0]);
  });
}

main();
