Here is a basic implementation of an autocomplete component in React without relying on any third-party packages:
```
import React, { useState, useEffect } from 'react';

const Autocomplete = ({ options, onSelect }) => {
  const [inputValue, setInputValue] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(-1);

  useEffect(() => {
    const handleInputValueChange = (event) => {
      const value = event.target.value;
      setInputValue(value);
      setSuggestions(getSuggestions(value));
    };

    const handleSuggestionsClick = (index) => {
      onSelect(options[index]);
      setInputValue('');
    };

    const getSuggestions = (value) => {
      const matchingOptions = options.filter((option) => {
        return option.includes(value);
      });
      return matchingOptions.map((option) => {
        return option;
      });
    };

    const handleArrowDown = () => {
      if (activeSuggestionIndex < suggestions.length - 1) {
        setActiveSuggestionIndex(activeSuggestionIndex + 1);
      }
    };

    const handleArrowUp = () => {
      if (activeSuggestionIndex > 0) {
        setActiveSuggestionIndex(activeSuggestionIndex - 1);
      }
    };

    const handleEnter = () => {
      onSelect(suggestions[activeSuggestionIndex]);
      setInputValue('');
    };

    document.addEventListener('keydown', (event) => {
      if (event.key === 'ArrowDown') {
        handleArrowDown();
      } else if (event.key === 'ArrowUp') {
        handleArrowUp();
      } else if (event.key === 'Enter') {
        handleEnter();
      }
    });

    document.addEventListener('click', () => {
      setActiveSuggestionIndex(-1);
    });

    document.getElementById('autocomplete-input').addEventListener('input', handleInputValueChange);

    return () => {
      document.removeEventListener('keydown', handleArrowDown);
      document.removeEventListener('keydown', handleArrowUp);
      document.removeEventListener('keydown', handleEnter);
      document.removeEventListener('click', () => {
        setActiveSuggestionIndex(-1);
      });
      document.getElementById('autocomplete-input').removeEventListener('input', handleInputValueChange);
    };
  }, []);

  return (
    <div>
      <input
        id="autocomplete-input"
        type="text"
        value={inputValue}
        onChange={(event) => handleInputValueChange(event)}
        placeholder="Type to autocomplete"
      />
      {suggestions.length > 0 && (
        <ul>
          {suggestions.map((suggestion, index) => (
            <li
              key={index}
              className={activeSuggestionIndex === index ? 'active' : ''}
              onClick={() => handleSuggestionsClick(index)}
            >
              {suggestion}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Autocomplete;
```
This component takes two props:

* `options`: an array of strings that are the possible autocomplete options
* `onSelect`: a function that is called when an option is selected, which should take the selected option as an argument

The component uses the following state:

* `inputValue`: the current value of the input field
* `suggestions`: an array of strings that are the possible suggestions based on the input value
* `activeSuggestionIndex`: the index of the currently active suggestion (i.e. the one that will be selected when Enter is pressed)

