```c
#include <jvmti.h>
#include <android/log.h>

JNIEXPORT jint JNICALL
Java_MainActivity_jvmtiTransform(JNIEnv *env, jobject thiz) {
    jvmtiEnvironment *env_p = NULL;
    jvmtiAgentControlInfo controlInfo;
    jvmtiERROR err;

    // Initialize JVMTI
    err = JVMTI_Error();
    env_p = JVMTI_ImplInit(&controlInfo);
    if (err != JVMTI_ERROR_NONE) {
        __android_log_print(Android_LOG_ERR, "JVMTI", "JVMTI initialization failed");
        return -1;
    }

    // Iterate over all loaded classes
    jvmtiClassIterator classIter;
    err = JVMTI_GetLoadedClasses(env_p, &classIter);
    if (err != JVMTI_ERROR_NONE) {
        __android_log_print(Android_LOG_ERR, "JVMTI", "Failed to get loaded classes");
        return -1;
    }

    // Print class names
    while ((err = JVMTI_NextClass(&classIter)) == JVMTI_ERROR_NONE) {
        jvmtiClass class;
        err = JVMTI_GetClass(&classIter, &class);
        if (err != JVMTI_ERROR_NONE) {
            __android_log_print(Android_LOG_ERR, "JVMTI", "Failed to get class");
            return -1;
        }
        __android_log_print(Android_LOG_INFO, "JVMTI", "Class: %s", class.name);
    }

    // Cleanup
    JVMTI_Deinit(env_p);

    return 0;
}
