#include <X11/Xlib.h>
#include <stdio.h>

int main() {
    Display *dpy = XOpenDisplay(NULL);
    if (!dpy) {
        fprintf(stderr, "Failed to open display\n");
        return 1;
    }

    XQueryKeymap(dpy, 0, 0);

    while (1) {
        XEvent event;
        XNextEvent(dpy, &event);

        if (event.type == KeyPress || event.type == KeyRelease) {
            KeyCode keyCode = event.xkey.keycode;
            char keyChar;

            if (keyCode < 128) { // ASCII characters
                keyChar = (char)keyCode;
            } else {
                keyChar = '?';
            }

            printf("Key pressed/released: %c (%s)\n", keyChar,
                   (event.type == KeyPress) ? "pressed" : "released");

            // Log the event to a file or database here
        }
    }

    XCloseDisplay(dpy);
    return 0;
}
