const double FUNC(double x) { return x * x; } // функция для интегрирования

double integralRect(double a, double b, int n) {
    double sum = 0;
    double h = (b - a) / (double)n;
    for (int i = 0; i < n; i++) {
        sum += h * FUNC(a + i * h);
    }
    return sum;
}

double integralTrap(double a, double b, int n) {
    double sum = 0;
    double h = (b - a) / (double)n;
    for (int i = 0; i < n; i++) {
        sum += (FUNC(a + i * h) + FUNC(a + (i + 1) * h)) * h / 2;
    }
    return sum;
}

double integralSimpson(double a, double b, int n) {
    double sum = 0;
    double h = (b - a) / (double)n;
    for (int i = 0; i < n; i++) {
        if (i == 0 || i == n - 1) {
            sum += h * FUNC(a + i * h);
        } else if (i % 2 == 0) {
            sum += 2 * h * FUNC(a + i * h);
        } else {
            sum += 4 * h * FUNC(a + i * h);
        }
    }
    return sum;
}

HANDLE hMutex;
double result = 0;

