        double x = LX + j * h;
        integral += h * FUNC(x);
        Sleep(rand() % 100 + 1); // задержка для моделирования работы потока
    }
    if (i == 0) {
        result = integralRect(LX, RX, N);
    } else if (i == 1) {
        result = integralTrap(LX, RX, N);
    } else {
        result = integralSimpson(LX, RX, N);
    }
    WaitForSingleObject(hMutex, INFINITE);
    cout << "Thread " << i << " calculated result: " << result << endl;
    ReleaseMutex(hMutex);
}

int main() {
