  ElmPDF := TElmPDF.Create(nil);

  // Load the source PDF file
  PDFFile := ElmPDF.LoadFromFile(SourcePDF);

  // Rotate the PDF file by the specified angle
  ElmPDF.Rotate(PDFFile, Angle, ElmPDF.roBoth); // Rotate both pages and contents

  // Save the rotated PDF file to the target file
  PDFFile.SaveToFile(TargetPDF);

  // Clean up
  PDFFile.Free;
  ElmPDF.Free;
end;
```
